// Normalize the Error Trigger payload into Loopmend's canonical contract.
// The eventId is derived from workflow + execution so n8n retries of this
// workflow re-send the SAME event (Loopmend ingests it once).
const crypto = require('crypto');
const p = $input.first().json;
const execution = p.execution || {};
const trigger = p.trigger || {};
const workflow = p.workflow || {};
if (!workflow.id) throw new Error('Error Trigger payload missing workflow.id');
const err = execution.error || trigger.error || {};
const executionId = execution.id ? String(execution.id) : `trigger_${crypto.createHash('sha256').update(`${workflow.id}:${err.message}:${trigger.timestamp || ''}`).digest('hex').slice(0, 16)}`;
const httpStatus = Number(err.httpCode || (err.context && err.context.httpCode) || NaN);
const event = {
  event: 'workflow.execution.failed',
  eventId: `n8n_${crypto.createHash('sha256').update(`${workflow.id}:${executionId}:failed`).digest('hex').slice(0, 32)}`,
  source: 'n8n',
  workflow: { id: String(workflow.id), name: workflow.name || 'Unnamed workflow' },
  execution: {
    id: executionId,
    status: 'error',
    mode: execution.mode || trigger.mode,
    retryOf: execution.retryOf ? String(execution.retryOf) : null,
    error: {
      message: String(err.message || err.description || 'Workflow execution failed').slice(0, 2000),
      node: execution.lastNodeExecuted || (err.node && err.node.name) || undefined,
      ...(Number.isFinite(httpStatus) ? { httpStatus, code: httpStatus === 429 ? 'RATE_LIMITED' : `HTTP_${httpStatus}` } : {}),
    },
  },
  occurredAt: new Date().toISOString(),
};
return [{ json: { event } }];

const crypto = require('crypto');
function sign(body) {
  const ts = Math.floor(Date.now() / 1000).toString();
  const nonce = crypto.randomBytes(16).toString('hex');
  const sig = crypto.createHmac('sha256', $env.LOOPMEND_WEBHOOK_SECRET).update(`${ts}.${nonce}.${body}`).digest('hex');
  return {
    'content-type': 'application/json',
    'x-loopmend-integration': $env.LOOPMEND_INTEGRATION_ID,
    'x-loopmend-timestamp': ts,
    'x-loopmend-nonce': nonce,
    'x-loopmend-signature': `v1=${sig}`,
  };
}

// Sign the exact bytes that will be sent. A fresh nonce per attempt keeps
// replay protection intact while the eventId keeps ingestion idempotent.
const body = JSON.stringify($input.first().json.event);
return [{ json: { body, headers: sign(body) } }];

// Loopmend rejected or is unreachable after bounded retries.
// Surface it loudly: this execution fails and appears in n8n's execution list.
const r = $input.first().json;
throw new Error(`Loopmend ingestion failed: HTTP ${r.statusCode} ${JSON.stringify(r.body?.error ?? r.body ?? '').slice(0, 300)}`);
